<?php
$eu=$editUser??null; $ep=$editPerm??[]; $mods=$mods??modules_catalog();
?>
<div class="user-fields-grid"><label>Nombre *<input name="nombre" value="<?=e($eu['nombre']??'')?>" required></label><label>Apellidos<input name="apellidos" value="<?=e($eu['apellidos']??'')?>"></label><label class="full">Correo electrónico *<input type="email" name="correo" value="<?=e($eu['correo']??'')?>" required></label><label>Rol *<select name="rol" required><?php $roles=is_superadmin()?['superadministrador','administrador','asesor','consulta']:['administrador','asesor','consulta']; foreach($roles as $rr): ?><option value="<?=$rr?>" <?=($eu['rol']??'asesor')===$rr?'selected':''?>><?=e(role_label($rr))?></option><?php endforeach; ?></select></label><label><?= $eu ? 'Nueva contraseña (opcional)' : 'Contraseña temporal *' ?><input type="password" name="password" minlength="8" <?=$eu?'':'required'?>><small>Mínimo 8 caracteres. El usuario podrá cambiarla desde Mi perfil.</small></label><label class="check-line full"><input type="checkbox" name="activo" value="1" <?=!isset($eu['activo'])||$eu['activo']?'checked':''?>> Usuario activo</label></div>
<div class="permissions-box"><div class="permissions-head"><h3>Permisos por módulo</h3><p>Ver permite consultar. Editar permite cambiar datos, estados o realizar envíos; Editar activa también Ver.</p></div><?php foreach($mods as $m=>$meta): $pv=!empty($ep[$m]['puede_ver']);$pe=!empty($ep[$m]['puede_editar']); ?><div class="permission-row"><div><b><?=e($meta[0])?></b><small><?=e($meta[1])?></small></div><label><input type="checkbox" name="ver[<?=e($m)?>]" value="1" <?=$pv?'checked':''?>> Ver</label><label><input type="checkbox" class="perm-edit" data-module="<?=e($m)?>" name="editar[<?=e($m)?>]" value="1" <?=$pe?'checked':''?>> Editar</label></div><?php endforeach; ?></div><div class="form-actions"><button class="primary" type="submit"><?= $eu ? 'Guardar cambios' : 'Crear usuario' ?></button></div>
<script>document.querySelectorAll('.perm-edit').forEach(x=>x.addEventListener('change',()=>{if(x.checked){const v=document.querySelector('input[name="ver['+x.dataset.module+']"]');if(v)v.checked=true;}}));</script>
